import re
from collections import Counter


class WordCount:
    def __init__(self):
        self._counts = Counter()

    def add_text(self, text):
        # BUG 1: splits on whitespace but doesn't strip punctuation
        words = text.lower().split()
        self._counts.update(words)

    def most_common(self, n):
        # BUG 2: sorts ascending instead of descending
        return sorted(self._counts.items(), key=lambda x: x[1])[:n]

    def total_count(self):
        # BUG 3: returns number of unique words, not total
        return len(self._counts)
